INSERT OR IGNORE INTO stories (id, date, month, summary_en, html_en, source_url, published) VALUES ('2026-05-06-qatar-draft-elaw-approved', '2026-05-06', '2026-05', 'Qatar''s Council of Ministers approved a draft e-invoicing law and implementing regulations on 6 May 2026 -- a real first step, but not a mandate. The draft still needs Shura Council review and the Amir''s assent, no implementation date or format has been published, and Qatar has not yet even implemented VAT.', '<h3>🇶🇦 Qatar takes its first legislative step on e-invoicing -- still a long way from a mandate</h3>
<p>On 6 May 2026, Qatar''s Council of Ministers approved a draft e-invoicing law and its implementing executive regulations -- confirmed by EY, KPMG, PwC, and Thomson Reuters/Pagero, all describing the same single action. It is the first concrete legislative movement this tracker has found on Qatari e-invoicing, and it puts Qatar alongside Saudi Arabia, the UAE, and Oman as a Gulf state actively building toward a mandate.</p>
<p>But "draft" means exactly that: the law still has to clear Shura Council review, then go to the Amir for enactment, then be published in the Official Gazette -- and as of this story''s publication, none of those steps has been independently confirmed to have happened. No implementation date, taxpayer threshold, technical format, or penalty structure has been officially released. Some industry commentary speculates a 2027 go-live or a Saudi/UAE-style rollout, but none of it is sourced to a Qatari government document. Underscoring how early-stage this all is: Qatar has still not implemented VAT at all, despite committing to do so under the 2016 GCC Unified VAT Agreement -- an unusual sequencing for a country now drafting an e-invoicing law.</p>', 'https://www.ey.com/en_gl/technical/tax-alerts/qatar-approves-draft-e-invoicing-law-and-implementing-regulations', 1);
INSERT OR IGNORE INTO story_countries (story_id, country_id) SELECT '2026-05-06-qatar-draft-elaw-approved', id FROM countries WHERE code = 'QA';
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-05-06-qatar-draft-elaw-approved', 'en', 'Qatar takes its first legislative step on e-invoicing -- still a long way from a mandate', 'Qatar''s Council of Ministers approved a draft e-invoicing law and implementing regulations on 6 May 2026 -- a real first step, but not a mandate. The draft still needs Shura Council review and the Amir''s assent, no implementation date or format has been published, and Qatar has not yet even implemented VAT.', '<h3>🇶🇦 Qatar takes its first legislative step on e-invoicing -- still a long way from a mandate</h3>
<p>On 6 May 2026, Qatar''s Council of Ministers approved a draft e-invoicing law and its implementing executive regulations -- confirmed by EY, KPMG, PwC, and Thomson Reuters/Pagero, all describing the same single action. It is the first concrete legislative movement this tracker has found on Qatari e-invoicing, and it puts Qatar alongside Saudi Arabia, the UAE, and Oman as a Gulf state actively building toward a mandate.</p>
<p>But "draft" means exactly that: the law still has to clear Shura Council review, then go to the Amir for enactment, then be published in the Official Gazette -- and as of this story''s publication, none of those steps has been independently confirmed to have happened. No implementation date, taxpayer threshold, technical format, or penalty structure has been officially released. Some industry commentary speculates a 2027 go-live or a Saudi/UAE-style rollout, but none of it is sourced to a Qatari government document. Underscoring how early-stage this all is: Qatar has still not implemented VAT at all, despite committing to do so under the 2016 GCC Unified VAT Agreement -- an unusual sequencing for a country now drafting an e-invoicing law.</p>');
